async function seedAdsenseBlogs() {
  console.log("🚀 Seeding all 25 Blog Posts with Simple, Humanized, Conversational Content...");
  for (const post of SEED_BLOG_POSTS) {
    const existing = await db.select().from(blogPosts).where(eq(blogPosts.slug, post.slug));
    if (existing.length > 0) {
      console.log(`🔄 Updating blog post: ${post.title}`);
      await db.update(blogPosts).set(post).where(eq(blogPosts.slug, post.slug));
    } else {
      console.log(`✨ Inserting new blog post: ${post.title}`);
      await db.insert(blogPosts).values(post);
    }
  }
  console.log("✅ All 25 Blog Posts Updated with Simple, Human-Written Content Successfully!");
  process.exit(0);
}

seedAdsenseBlogs().catch((err) => {
  console.error("❌ Error seeding blogs:", err);
  process.exit(1);
});
